let Z=2025,X=0;
function closeOptionsDropdown(){document.getElementById('optionsDropdown').classList.remove('active')}
function openModal(type){closeOptionsDropdown();clearAllActive();['bestPictureModal','screenplayModal','adaptedScreenplayModal','internationalModal','animatedFeatureModal','tomoPageModal'].forEach(id=>document.getElementById(id).style.display='none');TH.style.display='none';let modalId,catIdx,title;if(type==='picture'){modalId='bestPictureModal';catIdx=0;title='Best Picture Winners & Nominees'}else if(type==='screenplay'){modalId='screenplayModal';catIdx=1;title='Best Original Screenplay Winners & Nominees'}else if(type==='adapted'){modalId='adaptedScreenplayModal';catIdx=2;title='Best Adapted Screenplay Winners & Nominees'}else if(type==='international'){modalId='internationalModal';catIdx=3;title='Best International Feature Winners & Nominees'}else{modalId='animatedFeatureModal';catIdx=4;title='Best Animated Feature Winners & Nominees'}document.getElementById(modalId).style.display='flex';document.querySelectorAll('.category-row').forEach(r=>{r.classList.remove('active-cat','picture','screenplay','adapted','international','animated')});const cr=document.querySelectorAll('.category-row')[catIdx];cr.classList.add('active-cat');cr.classList.add(type);FH.classList.remove('picture','screenplay','adapted','international','animated');FH.classList.add(type);FH.style.display='flex';document.getElementById('floatingHeaderSub').innerHTML=title+' <span class="archive-tag">ARCHIVE</span>';document.getElementById('floatingCloseBtn').onclick=closeModal}
function closeModal(){clearAllActive();['bestPictureModal','screenplayModal','adaptedScreenplayModal','internationalModal','animatedFeatureModal'].forEach(id=>document.getElementById(id).style.display='none');FH.style.display='none';FH.classList.remove('picture','screenplay','adapted','international','animated')}
function openOscarZoom(y,i,type){closeOptionsDropdown();SL.style.display='none';Z=y;X=i;window._currentZoomType=type;let n;if(type==='screenplay')n=S2[y];else if(type==='adapted')n=AS2[y];else if(type==='international')n=IF[y];else if(type==='animated')n=AF[y];else n=D[y];const movie=n[i];currentZoomedMovie={title:movie.t,subtitle:'',year:movie.y,genre:movie.g,poster:movie.p};try{localStorage.setItem('lastZoomedMovie',JSON.stringify(currentZoomedMovie))}catch(e){}document.getElementById('zoomedImgOscar').src=movie.p;document.getElementById('zoomCounterOscar').textContent=`${i+1}/${n.length}`;document.getElementById('zoomOverlayOscar').classList.add('active');document.getElementById('zmTitle').textContent=movie.t;document.getElementById('zmMeta').textContent=`${movie.y} • ${movie.g}`;document.getElementById('zoomedDetails').style.display='block'}
function closeOscarZoom(){document.getElementById('zoomOverlayOscar').classList.remove('active');document.getElementById('zoomedDetails').style.display='none';SL.style.display='none'}
function navOscarZoom(d){let n;if(window._currentZoomType==='screenplay')n=S2[Z];else if(window._currentZoomType==='adapted')n=AS2[Z];else if(window._currentZoomType==='international')n=IF[Z];else if(window._currentZoomType==='animated')n=AF[Z];else n=D[Z];X=(X+d+n.length)%n.length;const movie=n[X];currentZoomedMovie={title:movie.t,subtitle:'',year:movie.y,genre:movie.g,poster:movie.p};try{localStorage.setItem('lastZoomedMovie',JSON.stringify(currentZoomedMovie))}catch(e){}document.getElementById('zoomedImgOscar').src=movie.p;document.getElementById('zoomCounterOscar').textContent=`${X+1}/${n.length}`;document.getElementById('zmTitle').textContent=movie.t;document.getElementById('zmMeta').textContent=`${movie.y} • ${movie.g}`;document.getElementById('zoomedDetails').style.display='block'}
function openMyPage(){closeOptionsDropdown();clearAllActive();MB.classList.add('active-mypage');['bestPictureModal','screenplayModal','adaptedScreenplayModal','internationalModal','animatedFeatureModal'].forEach(id=>document.getElementById(id).style.display='none');FH.style.display='none';FH.classList.remove('picture','screenplay','adapted','international','animated');document.getElementById('tomoPageModal').style.display='flex';TH.style.display='flex';renderMyPage()}
function closeTomoPage(){document.getElementById('tomoPageModal').style.display='none';TH.style.display='none';MB.classList.remove('active-mypage');if(!isLoggedIn){showToast('💡 Sign up for free to save your data','','default');openLoginModal()}}
function clearAllActive(){document.querySelectorAll('.category-row').forEach(r=>{r.classList.remove('active-cat','picture','screenplay','adapted','international','animated')});MB.classList.remove('active-mypage')}
function showToast(m,s,position='center-center'){const existing=document.querySelector('.toast-message');if(existing)existing.remove();const toast=document.createElement('div');toast.className='toast-message';if(position){toast.classList.add(position)}toast.innerHTML=m+(s?`<span class="toast-subtitle">${s}</span>`:'');document.body.appendChild(toast);setTimeout(()=>{toast.style.opacity='0';setTimeout(()=>toast.remove(),300)},3500)}
function addToWatchLater(d){if(myWatchLater.some(m=>m.title===d.title&&m.subtitle===d.subtitle&&m.year===d.year)){showToast('Already in your Watch Later','⚠️');return}if(!isLoggedIn){freeWatchLaterCount++;if(freeWatchLaterCount>FREE_LIMIT){pendingLoginAction=()=>addToWatchLater(d);openLoginModal();return}}myWatchLater.push({title:d.title,subtitle:d.subtitle||'',year:d.year,genre:d.genre||'',poster:d.poster});showToast('Added to Watch Later','✅');if(document.getElementById('tomoPageModal').style.display==='flex')renderMyPage()}
function openRatingPopup(d){if(!isLoggedIn){freeRatingsCount++;if(freeRatingsCount>FREE_LIMIT){pendingLoginAction=()=>openRatingPopup(d);openLoginModal();return}}currentRatingMovie=d;document.body.classList.add('rating-open');const popup=document.getElementById('ratingPopupPoster');popup.src=d.poster;popup.onerror=()=>popup.src='https://placehold.co/300x450/2d3748/ffffff?text=Movie';document.getElementById('ratingPopupTitle').textContent=(d.title+' '+(d.subtitle||'')).trim();document.getElementById('ratingPopupYear').textContent=d.year;document.getElementById('ratingPopupInput').value='';document.getElementById('ratingPopupSubmit').classList.remove('active');document.getElementById('ratingPopupOverlay').classList.add('active');document.getElementById('ratingPopupInput').focus()}
function closeRatingPopup(){document.body.classList.remove('rating-open');document.getElementById('ratingPopupOverlay').classList.remove('active');currentRatingMovie=null;window._editingRatingIndex=undefined}
function submitRating(){if(!currentRatingMovie)return;const val=parseFloat(document.getElementById('ratingPopupInput').value);if(isNaN(val)||val<0.1||val>10){showToast('Please enter a number between 0.1 and 10','⚠️');return}const rounded=Math.round(val*10)/10;if(window._editingRatingIndex!==undefined){myRatings[window._editingRatingIndex].rating=rounded;showToast('Rating updated: '+currentRatingMovie.title+' → ⭐ '+rounded+'/10','✏️');window._editingRatingIndex=undefined}else{const idx=myRatings.findIndex(r=>r.movie.title===currentRatingMovie.title&&r.movie.subtitle===currentRatingMovie.subtitle&&r.movie.year===currentRatingMovie.year);if(idx>=0){myRatings[idx].rating=rounded;showToast('Rating updated: '+currentRatingMovie.title+' → ⭐ '+rounded+'/10','✏️')}else{myRatings.push({movie:{title:currentRatingMovie.title,subtitle:currentRatingMovie.subtitle||'',year:currentRatingMovie.year,genre:currentRatingMovie.genre||'',poster:currentRatingMovie.poster},rating:rounded});showToast('Added to My Ratings: '+currentRatingMovie.title+' → ⭐ '+rounded+'/10','⭐')}}closeRatingPopup();if(document.getElementById('tomoPageModal').style.display==='flex')renderMyPage()}
function openConfirmDialog(type,index,movieName){pendingDelete={type,index};document.getElementById('confirmMovieName').textContent=movieName;document.getElementById('confirmOverlay').classList.add('active')}
function closeConfirmDialog(){document.getElementById('confirmOverlay').classList.remove('active');pendingDelete=null}
function executeDelete(){if(!pendingDelete)return;if(pendingDelete.type==='watchlater'){const movie=myWatchLater[pendingDelete.index];trashBin.push({type:'watchlater',data:{...movie}});myWatchLater.splice(pendingDelete.index,1);showToast('Moved to Trash: '+movie.title+' '+movie.subtitle,'🗑️')}else if(pendingDelete.type==='rating'){const sorted=[...myRatings].sort((a,b)=>b.rating-a.rating);const item=sorted[pendingDelete.index];const origIdx=myRatings.findIndex(r=>r.movie.title===item.movie.title&&r.movie.subtitle===item.movie.subtitle&&r.movie.year===item.movie.year);if(origIdx>=0){trashBin.push({type:'rating',data:{...item}});myRatings.splice(origIdx,1);showToast('Moved to Trash: '+item.movie.title+' '+item.movie.subtitle,'🗑️')}}closeConfirmDialog();updateTrashCount();renderMyPage();if(document.getElementById('trashModalOverlay').classList.contains('active'))renderTrashModal()}
function restoreFromTrash(index){const item=trashBin[index];if(!item)return;if(item.type==='watchlater'){myWatchLater.push({...item.data});showToast('Restored: '+item.data.title+' '+item.data.subtitle,'↻')}else if(item.type==='rating'){myRatings.push({...item.data});showToast('Restored: '+item.data.movie.title+' '+item.data.movie.subtitle,'↻')}trashBin.splice(index,1);updateTrashCount();renderMyPage();renderTrashModal()}
function deleteFromTrash(index){const item=trashBin[index];const name=item.type==='watchlater'?item.data.title+' '+item.data.subtitle:item.data.movie.title+' '+item.data.movie.subtitle;trashBin.splice(index,1);showToast('Permanently deleted: '+name,'❌');updateTrashCount();renderTrashModal()}
function emptyTrash(){if(trashBin.length===0)return;trashBin=[];showToast('Trash emptied','🗑️');updateTrashCount();renderTrashModal()}
function updateTrashCount(){document.getElementById('trashCount').textContent=trashBin.length;document.getElementById('trashModalCount').textContent=trashBin.length;const badge=document.querySelector('.trash-icon-btn .trash-badge');if(badge){badge.textContent=trashBin.length;if(trashBin.length===0){badge.classList.add('hidden')}else{badge.classList.remove('hidden')}}}
function openTrashModal(){closeOptionsDropdown();document.getElementById('trashModalOverlay').classList.add('active');renderTrashModal()}
function closeTrashModal(){document.getElementById('trashModalOverlay').classList.remove('active')}
function renderTrashModal(){const body=document.getElementById('trashModalBody'),footer=document.getElementById('trashModalFooter');updateTrashCount();if(trashBin.length===0){body.innerHTML='<div class="trash-modal-empty">Trash is empty</div>';footer.style.display='none'}else{let html='';trashBin.forEach((item,i)=>{let title='',poster='',typeClass='',typeLabel='',meta='';if(item.type==='watchlater'){title=item.data.title+' '+item.data.subtitle;poster=item.data.poster;typeClass='type-wl';typeLabel='Watch Later';meta=item.data.year+' • '+item.data.genre}else{title=item.data.movie.title+' '+item.data.movie.subtitle;poster=item.data.movie.poster;typeClass='type-rating';typeLabel='⭐ '+item.data.rating+'/10';meta=item.data.movie.year+' • '+item.data.movie.genre}html+=`<div class="trash-modal-item"><img class="trash-item-poster" src="${poster}" onerror="this.src='https://placehold.co/300x450/2d3748/ffffff?text=Movie'"><div class="trash-item-info"><div class="trash-item-title">${title}</div><div class="trash-item-meta">${meta}</div><span class="trash-item-type ${typeClass}">${typeLabel}</span></div><div class="trash-item-actions"><button class="trash-btn restore" onclick="restoreFromTrash(${i})" title="Restore">↻</button><button class="trash-btn delete" onclick="deleteFromTrash(${i})" title="Delete permanently">✕</button></div></div>`});body.innerHTML=html;footer.style.display='block'}}
function openLoginModal(){closeOptionsDropdown();if(isLoggedIn){showToast('✅ You are logged in as '+currentUser,'','default');openAccountOptions();return}document.getElementById('loginModalOverlay').classList.add('active')}
function closeLoginModal(){document.getElementById('loginModalOverlay').classList.remove('active');pendingLoginAction=null}
function updateLoginUI(){document.getElementById('loginMenuItem').textContent=isLoggedIn?currentUser:'Login'}
