function closeChangeCredentials(){document.getElementById('changeCredentialsOverlay').classList.remove('active')}
function updateAccount(){const newUser=document.getElementById('newUsername').value.trim(),newPass=document.getElementById('newPassword').value;if(!newUser&&!newPass){showToast('⚠️ No changes made.','');return}if(newUser){currentUser=newUser;updateLoginUI()}if(newPass){}closeChangeCredentials();closeAccountOptions();const msg=newUser&&newPass?'✅ Username & password updated!':newUser?'✅ Username updated!':'✅ Password updated!';showToast(msg,'','center-center')}
