function handleDragLeave(e){this.classList.remove('drag-over')}
function handleDrop(e){e.preventDefault();e.stopPropagation();this.classList.remove('drag-over');document.querySelectorAll('.mypage-movie-item').forEach(el=>el.classList.remove('drag-target'));if(!draggedItem)return;if(draggedType==='ratings'){const tg=this.closest('.rating-group');if(!tg){showToast('❌ Cannot move','Drag within Ratings list only');return}if(tg.dataset.rating!==draggedRating){showToast('❌ Cannot move','Drag within same rating group only');return}const ti=e.target.closest('.mypage-movie-item');if(!ti||ti===draggedItem||ti.dataset.rating!==draggedRating)return;updateRatingsOrder(draggedRating,draggedIndex,parseInt(ti.dataset.index));renderMyPage()}else if(draggedType==='watchlater'){if(!this.classList.contains('watchlater-list-container')){showToast('❌ Cannot move','Drag within Watch Later list only');return}const ti=e.target.closest('.mypage-movie-item');if(!ti||ti===draggedItem||ti.dataset.wlIndex===undefined)return;const tIdx=parseInt(ti.dataset.wlIndex),temp=myWatchLater[draggedIndex];myWatchLater.splice(draggedIndex,1);myWatchLater.splice(tIdx,0,temp);showToast('✅ Order updated','Watch Later reordered');renderMyPage()}}
function updateRatingsOrder(rating,fromIdx,toIdx){const same=[];myRatings.forEach((item,i)=>{if(item.rating===parseFloat(rating))same.push({...item,_origIndex:i})});const temp=same[fromIdx];same.splice(fromIdx,1);same.splice(toIdx,0,temp);const nr=[];let c=0;myRatings.forEach(item=>{if(item.rating===parseFloat(rating)){const ni=same[c];nr.push({movie:ni.movie,rating:ni.rating});c++}else nr.push(item)});myRatings=nr;showToast('✅ Order updated',`⭐ ${rating} group reordered`)}
/* ============================================================
   SUPABASE AUTH INIT — RUNS AT PAGE LOAD
   ============================================================ */
document.addEventListener('DOMContentLoaded',()=>{injectLoginButtons();attachAuthListener()});
